import{_ as l,a0 as d,w as o,s as p,I as s,x as e,a1 as n,A as a,ao as g}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Linux 中使用 find | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 find | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 find | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 find | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180427 How to use FIND in Linux","title":"如何在 Linux 中使用 find","tag":"201805","desc":""},"relativePath":"201805/20180427 How to use FIND in Linux.md","filePath":"[post].md"}'),r={name:"201805/20180427 How to use FIND in Linux.md"};function u(h,i,k,c,f,b){const t=d("Link");return o(),p("div",null,[i[20]||(i[20]=s("h1",{id:"如何在-linux-中使用-find",tabindex:"-1"},[e("如何在 Linux 中使用 find "),s("a",{class:"header-anchor",href:"#如何在-linux-中使用-find","aria-label":"Permalink to “如何在 Linux 中使用 find”"},"​")],-1)),i[21]||(i[21]=s("blockquote",null,[s("p",null,[e("使用正確的參數，"),s("code",null,"find"),e(" 命令是在你的系統上找到數據的強大而靈活的方式。")])],-1)),i[22]||(i[22]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/rh_003499_01_linux31x_cc.png?itok=Pvim4U-B",alt:""})],-1)),s("p",null,[i[1]||(i[1]=e("在",-1)),n(t,{href:"https://linux.cn/article-9585-1.html"},{default:a(()=>[...i[0]||(i[0]=[e("最近的一篇文章",-1)])]),_:1}),i[2]||(i[2]=e("中，Lewis Cowles 介紹了 ",-1)),i[3]||(i[3]=s("code",null,"find",-1)),i[4]||(i[4]=e(" 命令。",-1))]),i[23]||(i[23]=g('<p><code>find</code> 是日常工具箱中功能更強大、更靈活的命令列工具之一，因此值得花費更多的時間。</p><p>最簡單的，<code>find</code> 跟上路徑尋找一些東西。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /</span></span></code></pre></div><p>它將找到（並打印出）系統中的每個文件。而且由於一切都是文件，你會得到很多需要整理的輸出。這可能不能幫助你找到你要找的東西。你可以改變路徑參數來縮小範圍，但它不會比使用 <code>ls</code> 命令更有幫助。所以你需要考慮你想要找的東西。</p><p>也許你想在主目錄中找到所有的 JPEG 文件。 <code>-name</code> 參數允許你將結果限制為與給定模式匹配的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ -name &#39;*jpg&#39;</span></span></code></pre></div><p>可是等等！如果它們中的一些是大寫的擴展名會怎麼樣？<code>-iname</code> 就像 <code>-name</code>，但是不區分大小寫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ -iname &#39;*jpg&#39;</span></span></code></pre></div><p>很好！但是 8.3 名稱方案是如此的老。一些圖片可能是 .jpeg 擴展名。幸運的是，我們可以將模式用“或”（表示為 <code>-o</code>）來組合。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ ( -iname &#39;jpeg&#39; -o -iname &#39;jpg&#39; )</span></span></code></pre></div><p>我們正在接近目標。但是如果你有一些以 jpg 結尾的目錄呢？ （為什麼你要命名一個 <code>bucketofjpg</code> 而不是 <code>pictures</code> 的目錄就超出了本文的範圍。）我們使用 <code>-type</code> 參數修改我們的命令來查找文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ \\( -iname &#39;*jpeg&#39; -o -iname &#39;*jpg&#39; \\) -type f</span></span></code></pre></div><p>或者，也許你想找到那些命名奇怪的目錄，以便稍後重命名它們：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ \\( -iname &#39;*jpeg&#39; -o -iname &#39;*jpg&#39; \\) -type d</span></span></code></pre></div><p>你最近拍了很多照片，所以讓我們把它縮小到上週更改的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ \\( -iname &#39;*jpeg&#39; -o -iname &#39;*jpg&#39; \\) -type f -mtime -7</span></span></code></pre></div><p>你可以根據文件狀態更改時間 （<code>ctime</code>）、修改時間 （<code>mtime</code>） 或訪問時間 （<code>atime</code>） 來執行時間過濾。 這些是在幾天內，所以如果你想要更細粒度的控制，你可以表示為在幾分鐘內（分別是 <code>cmin</code>、<code>mmin</code> 和 <code>amin</code>）。 除非你確切地知道你想要的時間，否則你可能會在 <code>+</code> （大於）或 <code>-</code> （小於）的後面加上數字。</p><p>但也許你不關心你的照片。也許你的磁盤空間不夠用，所以你想在 <code>log</code> 目錄下找到所有巨大的（讓我們定義為“大於 1GB”）文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /var/log -size +1G</span></span></code></pre></div><p>或者，也許你想在 <code>/data</code> 中找到 bcotton 擁有的所有文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /data -owner bcotton</span></span></code></pre></div><p>你還可以根據權限查找文件。也許你想在你的主目錄中找到對所有人可讀的文件，以確保你不會過度分享。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ -perm -o=r</span></span></code></pre></div><p>這篇文章只説了 <code>find</code> 能做什麼的表面。將測試條件與布爾邏輯相結合可以為你提供難以置信的靈活性，以便準確找到要查找的文件。並且像 <code>-exec</code> 或 <code>-delete</code> 這樣的參數，你可以讓 <code>find</code> 對它發現的內容採取行動。你有任何最喜歡的 <code>find</code> 表達式麼？在評論中分享它們！</p><hr>',25)),s("p",null,[i[6]||(i[6]=e("via: ",-1)),n(t,{href:"https://opensource.com/article/18/4/how-use-find-linux"},{default:a(()=>[...i[5]||(i[5]=[e("https://opensource.com/article/18/4/how-use-find-linux",-1)])]),_:1})]),s("p",null,[i[11]||(i[11]=e("作者：",-1)),n(t,{href:"https://opensource.com/users/bcotton"},{default:a(()=>[...i[7]||(i[7]=[e("Ben Cotton",-1)])]),_:1}),i[12]||(i[12]=e(" 選題：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[8]||(i[8]=[e("lujun9972",-1)])]),_:1}),i[13]||(i[13]=e(" 譯者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:a(()=>[...i[9]||(i[9]=[e("geekpi",-1)])]),_:1}),i[14]||(i[14]=e(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[10]||(i[10]=[e("wxy",-1)])]),_:1})]),s("p",null,[i[17]||(i[17]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[15]||(i[15]=[e("LCTT",-1)])]),_:1}),i[18]||(i[18]=e(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:a(()=>[...i[16]||(i[16]=[e("Linux中國",-1)])]),_:1}),i[19]||(i[19]=e(" 榮譽推出",-1))])])}const y=l(r,[["render",u]]);export{C as __pageData,y as default};
